head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL35700_POP";
scwin.subTitle0 = null;
scwin.subTitle1 = null;
scwin.subTitle2 = null;
scwin.divType1 = null;
scwin.nonValue = null;
scwin.divType2 = null;
scwin.divType3 = null;
scwin.divType8 = null;
scwin.divType10 = null;
scwin.scrollDivType = null;
scwin.divType6 = null;
scwin.divType7 = null;
scwin.divType9 = null;
scwin.divType4 = null;
scwin.sum2 = null;
scwin.disc1 = null;
scwin.disc2 = null;
scwin.disc3 = null;
scwin.disc4 = null;
scwin.divType5 = null;
scwin.dataArr = null;
scwin.dataArr_trust = null;

// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.corpUsrTpCd

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.subTitle0 = $c.util.getComponent('subTitle0');
        scwin.subTitle1 = $c.util.getComponent('subTitle1');
        scwin.subTitle2 = $c.util.getComponent('subTitle2');
        scwin.divType1 = $c.util.getComponent('divType1');
        scwin.nonValue = $c.util.getComponent('nonValue');
        scwin.divType2 = $c.util.getComponent('divType2');
        scwin.divType3 = $c.util.getComponent('divType3');
        scwin.divType8 = $c.util.getComponent('divType8');
        scwin.divType10 = $c.util.getComponent('divType10');
        scwin.scrollDivType = $c.util.getComponent('scrollDivType');
        scwin.divType6 = $c.util.getComponent('divType6');
        scwin.divType7 = $c.util.getComponent('divType7');
        scwin.divType9 = $c.util.getComponent('divType9');
        scwin.divType4 = $c.util.getComponent('divType4');
        scwin.sum2 = $c.util.getComponent('sum2');
        scwin.disc1 = $c.util.getComponent('disc1');
        scwin.disc2 = $c.util.getComponent('disc2');
        scwin.disc3 = $c.util.getComponent('disc3');
        scwin.disc4 = $c.util.getComponent('disc4');
        scwin.divType5 = $c.util.getComponent('divType5');
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil35700_pop.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "txt_p25", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") === '11' || $c.session.getUserInfo("corpUsrTpCd") === '21'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        $c.util.getComponent("rd_mktGubun").setValue("1");
        (scwin.rd_mktGubun_onclick ? scwin.rd_mktGubun_onclick() : 0);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35700_pop.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
