        scwin.dataArr[1] = { stock_count: $c.util.getComponent("ipt_stockCount_r1").getValue(), parval: $c.util.getComponent("ipt_parval_r1").getValue(), list_amt: '' };
        scwin.dataArr[2] = { stock_count: $c.util.getComponent("ipt_stockCount_r2").getValue(), parval: $c.util.getComponent("ipt_parval_r2").getValue(), list_amt: '' };
        scwin.dataArr[3] = { stock_count: $c.util.getComponent("ipt_stockCount_r3").getValue(), parval: $c.util.getComponent("ipt_parval_r3").getValue(), list_amt: '' };
