        scwin.dataArr[5] = { stock_count: $c.util.getComponent("ipt_stockCount_r5").getValue(), parval: $c.util.getComponent("ipt_parval_r5").getValue(), list_amt: '' };
        scwin.dataArr[6] = { stock_count: $c.util.getComponent("ipt_stockCount_r6").getValue(), parval: $c.util.getComponent("ipt_parval_r6").getValue(), list_amt: '' };
        scwin.dataArr[7] = { stock_count: $c.util.getComponent("ipt_stockCount_r7").getValue(), parval: $c.util.getComponent("ipt_parval_r7").getValue(), list_amt: '' };
