        scwin.dataArr[9] = { stock_count: $c.util.getComponent("ipt_stockCount_r9").getValue(), parval: $c.util.getComponent("ipt_parval_r9").getValue(), list_amt: '' };
    }
    const type = $c.util.getComponent('ipt_kk').getValue();
    const listTp = $c.util.getComponent('dma_goTab1Req').get('listTp');
    let tot_list = 0;
    let list_comm_sum = 0;
    let list_comm_sum_add = 0;
    let inputFlag = false;
    if ($c.util.getComponent('dma_goTab1Req').get('mkt') === "1") {
        for (i = 0; i < scwin.dataArr.length; i++) {
            if (scwin.dataArr[i].stock_count !== "" && scwin.dataArr[i].parval !== "" && ($c.util.getComponent('ipt_checkGubun1').getValue() != null && String($c.util.getComponent('ipt_checkGubun1').getValue()) !== '') === false) {
                inputFlag = true;
                scwin.dataArr[i].list_amt = parseInt(scwin.delComma(scwin.dataArr[i].stock_count)) * parseInt(scwin.delComma(scwin.dataArr[i].parval));
                tot_list = (tot_list) + (scwin.dataArr[i].list_amt);
                let rt_rate = "0.0";
                let rt_rate2 = "0.0";
                if (listTp === "1") {
                    if ($c.util.getComponent("dma_goTab1Req").get("kk") === "1") {
                        rt_rate = scwin.rate_Stcok_1(tot_list);
                        list_comm_sum = Math.round(rt_rate);
                        rt_rate2 = scwin.rate_Stcok_1(scwin.dataArr[i].list_amt);
                        list_comm_sum_add = list_comm_sum_add + (rt_rate2);
                    } else {
                        if ($c.util.getComponent("dma_goTab1Req").get("kk") === "2") {
                            rt_rate = scwin.rate_Stcok_1(tot_list);
                            rt_rate = Math.floor(rt_rate / 3 / 100) * 100;
                            list_comm_sum = Math.round(rt_rate);
                            rt_rate2 = scwin.rate_Stcok_1(scwin.dataArr[i].list_amt);
                            rt_rate2 = rt_rate2 * 1 / 3;
                            list_comm_sum_add = list_comm_sum_add + (rt_rate2);
                        } else {
                            if ($c.util.getComponent("dma_goTab1Req").get("kk") === "3") {
                                rt_rate = scwin.rate_Bw(tot_list);
                                rt_rate = Math.floor(rt_rate / 3 / 100) * 100;
                                if (rt_rate < 100000) {
                                    rt_rate = 100000.0;
                                }
                                list_comm_sum = Math.round(rt_rate);
                                rt_rate2 = scwin.rate_Bw(scwin.dataArr[i].list_amt);
                                rt_rate2 = Math.floor(rt_rate2 / 3 / 100) * 100;
                                if (rt_rate2 < 100000) {
                                    rt_rate2 = 100000.0;
                                }
                                list_comm_sum_add = list_comm_sum_add + (rt_rate2);
                            } else {
                                if ($c.util.getComponent("dma_goTab1Req").get("kk") === "4") {
                                    rt_rate = scwin.rate_Bw(scwin.dataArr[i].list_amt);
                                    list_comm_sum = rt_rate;
                                    list_comm_sum_add = list_comm_sum_add + (rt_rate);
                                }
                            }
                        }
                    }
                } else {
                    if (listTp === "2") {
                        if ($c.util.getComponent("dma_goTab1Req").get("kk") === "1") {
                            rt_rate = scwin.rate_Stcok_2(tot_list);
                            list_comm_sum = Math.round(rt_rate);
                            rt_rate2 = scwin.rate_Stcok_2(scwin.dataArr[i].list_amt);
                            list_comm_sum_add = list_comm_sum_add + (rt_rate2);
                        } else {
                            if ($c.util.getComponent("dma_goTab1Req").get("kk") === "2") {
                                rt_rate = scwin.rate_Stcok_2(tot_list);
                                rt_rate = Math.floor(rt_rate / 3 / 100) * 100;
                                list_comm_sum = Math.round(rt_rate);
                                rt_rate2 = scwin.rate_Stcok_2(scwin.dataArr[i].list_amt);
                                rt_rate2 = rt_rate2 * 1 / 3;
                                list_comm_sum_add = list_comm_sum_add + (rt_rate2);
                            } else {
                                if ($c.util.getComponent("dma_goTab1Req").get("kk") === "3" && scwin.dataArr[i].list_amt > 0) {
                                    rt_rate = (i + 1) * 100000.0;
                                    list_comm_sum = Math.round(rt_rate);
                                    list_comm_sum_add = (rt_rate);
                                } else {
                                    if ($c.util.getComponent("dma_goTab1Req").get("kk") === "4" && scwin.dataArr[i].list_amt > 0) {
                                        rt_rate = (i + 1) * 300000.0;
                                        list_comm_sum = Math.round(rt_rate);
                                        list_comm_sum_add = (rt_rate);
                                    }
                                }
                            }
                        }
                    } else {
                        if (listTp === "3") {
                            if ($c.util.getComponent("dma_goTab1Req").get("kk") === "1") {
                                rt_rate = (i + 1) * 2000000;
                                list_comm_sum = Math.round(rt_rate);
                                list_comm_sum_add = (rt_rate);
                            } else {
                                if ($c.util.getComponent("dma_goTab1Req").get("kk") === "2") {
                                    rt_rate = (i + 1) * 300000;
                                    list_comm_sum = Math.round(rt_rate);
                                    list_comm_sum_add = (rt_rate);
                                } else {
                                    if ($c.util.getComponent("dma_goTab1Req").get("kk") === "3" && scwin.dataArr[i].list_amt > 0) {
                                        rt_rate = (i + 1) * 100000;
                                        list_comm_sum = Math.round(rt_rate);
                                        list_comm_sum_add = (rt_rate);
                                    } else {
                                        if ($c.util.getComponent("dma_goTab1Req").get("kk") === "4" && scwin.dataArr[i].list_amt > 0) {
                                            rt_rate = (i + 1) * 300000;
                                            list_comm_sum = Math.round(rt_rate);
                                            list_comm_sum_add = (rt_rate);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                if ((String($c.util.getComponent('ipt_checkGubun1').getValue() || "") !== "") && scwin.dataArr[i].list_amt !== "") {
