/**
 * @method
 * @name delComma
 * @description del Comma 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.delComma = function (obj) {
    return obj.replace(/,/g, "");
};

/**
 * @method
 * @name rate_konex
 * @description rate konex 처리
 * @param {Number} i i
 * @returns {void}
 * @hidden N
 */
scwin.rate_konex = function (i) {
    let rate = "0.0";
    if (i <= 10000000000.0) {
        rate = Math.ceil(i / 1000000000.0) * 30000.0;
    } else {
        if (i > 10000000000.0 && i <= 30000000000.0) {
            rate = 300000.0 + Math.ceil((i - 10000000000.0) / 1000000000.0) * 25000.0;
        } else {
            if (i > 30000000000.0 && i <= 50000000000.0) {
                rate = 800000.0 + Math.ceil((i - 30000000000.0) / 1000000000.0) * 20000.0;
            } else {
                if (i > 50000000000.0 && i <= 70000000000.0) {
                    rate = 1200000.0 + Math.ceil((i - 50000000000.0) / 1000000000.0) * 15000.0;
                } else {
                    if (i > 70000000000.0 && i <= 100000000000.0) {
                        rate = 1500000.0 + Math.ceil((i - 70000000000.0) / 1000000000.0) * 10000.0;
                    } else {
                        if (i > 100000000000.0 && i <= 200000000000.0) {
                            rate = 1800000.0 + Math.ceil((i - 100000000000.0) / 1000000000.0) * 5000.0;
                        } else {
                            if (i > 200000000000.0 && i <= 500000000000.0) {
                                rate = 2300000.0 + Math.ceil((i - 200000000000.0) / 1000000000.0) * 2500.0;
                            } else {
                                if (i > 500000000000.0) {
                                    rate = 3050000.0 + Math.ceil((i - 500000000000.0) / 1000000000.0) * 500.0;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    return rate;
};

/**
 * @method
 * @name rate_kosdaq_1
 * @description rate kosdaq 1 처리
 * @param {Number} i i
 * @param {*} type type
 * @returns {void}
 * @hidden N
 */
scwin.rate_kosdaq_1 = function (i, type) {
    let rate = "0.0";
    if (i <= 50000000000.0) {
        rate = 1000000;
    } else {
        if (i > 50000000000.0 && i <= 70000000000.0) {
            rate = 5000000.0 + Math.ceil((i - 50000000000.0) / 1000000000.0) * 70000.0;
        } else {
            if (i > 70000000000.0 && i <= 100000000000.0) {
                rate = 6400000.0 + Math.ceil((i - 70000000000.0) / 1000000000.0) * 60000.0;
            } else {
                if (i > 100000000000.0 && i <= 200000000000.0) {
                    rate = 8200000.0 + Math.ceil((i - 100000000000.0) / 1000000000.0) * 50000.0;
                } else {
                    if (i > 200000000000.0 && i <= 300000000000.0) {
                        rate = 13200000.0 + Math.ceil((i - 200000000000.0) / 1000000000.0) * 40000.0;
                    } else {
                        if (i > 300000000000.0 && i <= 400000000000.0) {
                            rate = 17200000.0 + Math.ceil((i - 300000000000.0) / 1000000000.0) * 30000.0;
                        } else {
                            if (i > 400000000000.0 && i <= 500000000000.0) {
                                rate = 20200000.0 + Math.ceil((i - 400000000000.0) / 1000000000.0) * 20000.0;
                            } else {
                                if (i > 500000000000.0) {
                                    rate = 22200000.0 + Math.ceil((i - 500000000000.0) / 1000000000.0) * 10000.0;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    if (rate > 200000000) {
        rate = "200000000";
    }
    if (type > 3) {
        rate = Math.floor(rate / 3 / 100) * 100;
    }
    return rate;
};

